  var label="stability-C-0.2-"+perturb+"-"+version;using var budget=new Budget155(label,0,45);Program155.Sources(label);var origin=Program155.State(0);var prior=Restore("C-0.0-v4",origin.Spec,budget.Guard);var original=Program155.Read<Run144>(Program154.Doc+"/native/S0-full-baseline-v1.json.gz");var sample=original.Riders[0].Samples.First(s=>Math.Abs(s.Input.Time-.2)<1e-8);if(RiderController.ReactionSeconds(origin.Spec)<=.2)throw new InvalidOperationException("Causal requeue requires latency greater than0.2s");
